-- Generated by execution/homework_sql.ts from docs/homework-2026-27/final/qaidah-hw5.json.
-- Loads homework 305 for 2026/27. Review, then apply with execution/apply_migration.ts.
-- Idempotent: re-running replaces the same papers again.

do $guard$ begin
  if exists (select 1 from submissions s join homeworks h on h.id = s.homework_id
             join auth.users u on u.id = s.student_id
             where h.number in (305) and coalesce(u.email, '') not like '%@bsms-demo.test') then
    raise exception 'a real student has work on a homework this load replaces; stop and ask';
  end if;
end $guard$;

-- Demo work on the replaced papers (answers, voice notes, attempts cascade).
delete from submissions where homework_id in (select id from homeworks where number in (305));
delete from questions where homework_id in (select id from homeworks where number in (305));

-- ── Homework 305: Tanwīn Practice (4 marks, 4 questions)
insert into homeworks (number, title, series, total_marks, is_graded, week_id, due_at, course_id, ordinal)
select 305, $q$Tanwīn Practice$q$, 'qaidah', 4, true, w.id, w.due_at, c.id, 5
  from weeks w, courses c where w.term_id = 1 and w.number = 5 and c.key = 'qaidah'
on conflict (number) do update set title = excluded.title, series = excluded.series, total_marks = excluded.total_marks,
  is_graded = true, course_id = excluded.course_id, ordinal = excluded.ordinal;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 1, 'text', 'manual', $q$Tanwīn with fatḥah. Read the following words and record yourself. Every word ends with a tanwīn, so each should end in an "n" sound: here, "an".$q$, 1, false, true, null, null, false
  from homeworks where number = 305;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 2, 'text', 'manual', $q$Tanwīn with kasrah. Read the following words and record yourself. Most end in "in"; the last word of each row has a fatḥah tanwīn, so it ends in "an".$q$, 1, false, true, null, null, false
  from homeworks where number = 305;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 3, 'text', 'manual', $q$Tanwīn with ḍammah. Read the following words and record yourself. Each ends in "un".$q$, 1, false, true, null, null, false
  from homeworks where number = 305;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 4, 'text', 'manual', $q$These short phrases from the Qur'an bring the tanwīn together with everything covered so far. Read them and record yourself.$q$, 1, false, true, null, null, false
  from homeworks where number = 305;

-- Audio needs questions.media (migration 0048); skipped until it exists.
do $media$ begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'questions' and column_name = 'media') then
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw5-1-1.jpg","alt":"Five words ending in tanwīn with fatḥah","width":640,"height":90},{"src":"/images/homework/qaidah/hw5-1-2.jpg","alt":"Four more words ending in tanwīn with fatḥah","width":640,"height":108}]}$q$::jsonb where position = 1 and homework_id = (select id from homeworks where number = 305);
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw5-2.jpg","alt":"Eight words ending in tanwīn, mostly with kasrah","width":640,"height":225}]}$q$::jsonb where position = 2 and homework_id = (select id from homeworks where number = 305);
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw5-3.jpg","alt":"Five words ending in tanwīn with ḍammah","width":640,"height":84}]}$q$::jsonb where position = 3 and homework_id = (select id from homeworks where number = 305);
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw5-4.jpg","alt":"Three short phrases from the Qur'an with tanwīn","width":640,"height":92}]}$q$::jsonb where position = 4 and homework_id = (select id from homeworks where number = 305);
  end if;
end $media$;

select number, title, total_marks, (select count(*) from questions q where q.homework_id = h.id) as questions
  from homeworks h where number in (305) order by number;
